01-hull.diff:
@@ -1,8 +1,9 @@
 name: ship
 description: >
   Player ship: a wooden two-masted brig. Oak hull with a raised stern castle (lit brass lanterns),
-  forecastle, bowsprit, bare masts with yards. Top-down 3/4 view, no water (it sits on a moving sea).
-  8 headings.
+  forecastle, bowsprit. Square sails braced to catch the wind on both masts, a jib to the bowsprit,
+  red pennants. Top-down 3/4 view, no water (it sits on a moving sea). 8 headings; the pennants
+  flutter in the "sail" animation.
 size: [92, 70]
 pivot: [46, 46]
 origin: [32, 0, 0]          # the hull's centre at the waterline lands on the pivot
@@ -19,6 +20,8 @@
   mast: { keys: ["1", "2", "4"] }
   lamp: { keys: ["e"] }                       # one key = unshaded: lanterns glow
   trim: { ramp: gold }
+  sail: { keys: ["8", "9", "a", "b"], two_sided: true }
+  flag: { ramp: red }

 parts:
   - hull: { from: [0, 0, 0], length: 64, beam: 19, height: 7, bow: 0.4, stern: 0.1, material: hull, top: deck, rim: rail }
@@ -38,7 +41,21 @@
   - cylinder: { base: [24, 0, 7], height: 36, material: mast }                             # main mast
   - cylinder: { base: [45, 0, 7], height: 30, material: mast }                             # fore mast
   - line: { from: [60, 0, 8], to: [73, 0, 14], material: mast }                            # bowsprit
-  - line: { from: [24, -9, 18], to: [24, 9, 18], material: mast }                          # yards
-  - line: { from: [24, -7, 32], to: [24, 7, 32], material: mast }
-  - line: { from: [45, -8, 16], to: [45, 8, 16], material: mast }
-  - line: { from: [45, -6, 28], to: [45, 6, 28], material: mast }
+  - sail: { at: [24, 0, 12], width: 20, height: 13, bulge: 2.2, brace: 30, material: sail, yard: mast }
+  - sail: { at: [24, 0, 27], width: 15, height: 9, bulge: 1.8, brace: 30, material: sail, yard: mast }
+  - sail: { at: [45, 0, 11], width: 17, height: 11, bulge: 2, brace: 30, material: sail, yard: mast }
+  - sail: { at: [45, 0, 24], width: 12, height: 8, bulge: 1.6, brace: 30, material: sail, yard: mast }
+  - triangle: { points: [[48, 0, 10], [70, 0, 13], [46, 0, 34]], material: sail }             # jib
+  - box: { from: [20, 0, 41], to: [24, 0, 42], material: flag }                                # pennants
+    id: pennant
+  - box: { from: [42, 0, 35], to: [44, 0, 36], material: flag }
+    id: fore_pennant
+
+animations:
+  sail:
+    fps: 6
+    poses:
+      - {}
+      - { pennant: { offset: [0, 1, 0] }, fore_pennant: { offset: [0, 1, 0] } }
+      - {}
+      - { pennant: { offset: [0, -1, 0] }, fore_pennant: { offset: [0, -1, 0] } }
